151	// 再发行、发起或接收新的转让；停用不影响已经落盘的任何记录。
152	func (r *Registry) DeactivateAccount(id string) error {
153		r.mu.Lock()
154		defer r.mu.Unlock()
155		if err := r.checkOpen(); err != nil {
156			return err
157		}
158		a, ok := r.state.Accounts[id]
159		if !ok {
160			return fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
161		}
162		if !a.Active {
163			return nil // 停用是幂等的终态
164		}
165		a.Active = false
166		r.state.Accounts[id] = a
