1	package registry
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8	)
9	
10	// setupBatchWorld 建立 alice（系列创建者）、bob、carol 三个可用账户与
11	// 系列 s1。
12	func setupBatchWorld(t *testing.T, r *Registry) {
13		t.Helper()
14		for _, id := range []string{"alice", "bob", "carol"} {
15			if err := r.RegisterAccount(id, ""); err != nil {
16				t.Fatal(err)
17			}
18		}
19		if err := r.CreateSeries("s1", "alice", "系列"); err != nil {
20			t.Fatal(err)
21		}
22	}
23	
24	func batchReq(rid string, entries ...IssueBatchEntry) IssueBatchRequest {
25		return IssueBatchRequest{
26			Operator: "alice", Reason: "整批首发", RequestID: rid,
27			SeriesID: "s1", BatchNo: "b1", Entries: entries,
28		}
29	}
30	
31	func be(item, holder string) IssueBatchEntry {
32		return IssueBatchEntry{ItemID: item, Metadata: "元-" + item, HolderID: holder}
33	}
34	
35	// ---- 基本成功流程 ----
36	
37	func TestIssueBatchSuccess(t *testing.T) {
38		r := mustCreate(t, tempDir(t))
39		setupBatchWorld(t, r)
40	
41		res, err := r.IssueBatch(batchReq("rb1",
42			be("i1", "bob"), be("i2", "carol"), be("i3", "bob")))
43		if err != nil {
44			t.Fatalf("IssueBatch: %v", err)
45		}
46		if res.Replayed || res.Err != nil {
47			t.Fatalf("unexpected result flags: %+v", res)
48		}
49		if len(res.Items) != 3 {
50			t.Fatalf("want 3 items, got %d", len(res.Items))
51		}
52		wantOwners := []string{"bob", "carol", "bob"}
53		for i, it := range res.Items {
54			wantID := fmt.Sprintf("i%d", i+1)
55			if it.ItemID != wantID || it.OwnerID != wantOwners[i] || it.Version != 1 {
56				t.Errorf("item %d: %+v", i, it)
57			}
58			if it.TxSeq != int64(i+1) {
59				t.Errorf("item %d: TxSeq = %d, want %d", i, it.TxSeq, i+1)
60			}
61		}
62		// 历史序号连续递增。
63		for i := 1; i < 3; i++ {
64			if res.Items[i].TxSeq != res.Items[i-1].TxSeq+1 {
65				t.Fatalf("TxSeq not consecutive: %+v", res.Items)
66			}
67		}
68	
69		// 各件可通过现有查询读取。
70		for i, it := range res.Items {
71			got, err := r.GetItem(it.ItemID)
72			if err != nil {
73				t.Fatalf("GetItem %s: %v", it.ItemID, err)
74			}
75			if got.SeriesID != "s1" || got.BatchNo != "b1" || got.Metadata != "元-"+it.ItemID {
76				t.Errorf("GetItem %s: %+v", it.ItemID, got)
77			}
78			if got.IssuedTxID != it.TxSeq {
79				t.Errorf("GetItem %s: IssuedTxID = %d, want %d", it.ItemID, got.IssuedTxID, it.TxSeq)
80			}
81			h, err := r.GetHolding(it.ItemID)
82			if err != nil {
83				t.Fatalf("GetHolding %s: %v", it.ItemID, err)
84			}
85			if h.OwnerID != wantOwners[i] || h.Version != 1 {
86				t.Errorf("GetHolding %s: %+v", it.ItemID, h)
87			}
88			hist, err := r.History(it.ItemID)
89			if err != nil {
90				t.Fatalf("History %s: %v", it.ItemID, err)
91			}
92			if len(hist) != 1 || hist[0].Kind != "issue" || hist[0].ToID != wantOwners[i] ||
