571		// 只发行一次：历史各一条。
572		for _, id := range []string{"i1", "i2"} {
573			hist, err := r.History(id)
574			if err != nil {
575				t.Fatal(err)
576			}
577			if len(hist) != 1 {
578				t.Fatalf("%s issued %d times", id, len(hist))
579			}
580		}
581	}
582	
583	// 不同请求与单件发行争用同一编号时，最多一个请求占用该编号。
584	func TestIssueBatchConcurrentIDContention(t *testing.T) {
585		r := mustCreate(t, tempDir(t))
586		setupBatchWorld(t, r)
587	
588		const n = 6
589		var wg sync.WaitGroup
590		errs := make([]error, n)
591		for i := 0; i < n; i++ {
592			wg.Add(1)
593			go func(i int) {
594				defer wg.Done()
595				if i%2 == 0 {
596					_, errs[i] = r.IssueBatch(batchReq(fmt.Sprintf("rb-%d", i), be("hot", "bob")))
597				} else {
598					req := issueReq("hot", "bob")
599					req.RequestID = fmt.Sprintf("rs-%d", i)
600					_, errs[i] = r.Issue(req)
601				}
602			}(i)
603		}
604		wg.Wait()
605		succeeded, alreadyExists := 0, 0
606		for i, err := range errs {
607			switch {
608			case err == nil:
609				succeeded++
610			case errors.Is(err, ErrAlreadyExists):
611				alreadyExists++
612			default:
613				t.Fatalf("goroutine %d: unexpected err %v", i, err)
614			}
615		}
616		if succeeded != 1 || alreadyExists != n-1 {
617			t.Fatalf("succeeded = %d, alreadyExists = %d, want 1 and %d", succeeded, alreadyExists, n-1)
618		}
619		hist, err := r.History("hot")
620		if err != nil {
621			t.Fatal(err)
622		}
623		if len(hist) != 1 {
624			t.Fatalf("hot issued %d times", len(hist))
625		}
626	}
627	
628	// 整批发行的藏品可创建代转授权并代转。
629	func TestIssueBatchItemAuthorization(t *testing.T) {
630		r := mustCreate(t, tempDir(t))
631		setupBatchWorld(t, r)
632		if _, err := r.IssueBatch(batchReq("rb1", be("i1", "bob"))); err != nil {
633			t.Fatal(err)
634		}
635		expires := r.now().Add(3600e9)
636		cres, err := r.CreateAuthorization(CreateAuthorizationRequest{
637			Operator: "bob", Reason: "委托", RequestID: "ra1", AuthID: "a1",
638			ItemID: "i1", TrusteeID: "carol", ToID: "alice",
639			ExpectedOwner: "bob", ExpectedVer: 1, ExpiresAt: expires,
640		})
641		if err != nil {
642			t.Fatalf("CreateAuthorization: %v", err)
643		}
644		if cres.Status != AuthActive {
645			t.Fatalf("status = %q", cres.Status)
646		}
647		pres, err := r.ProxyTransfer(ProxyTransferRequest{
648			Operator: "carol", Reason: "代转", RequestID: "rp1", AuthID: "a1",
649		})
650		if err != nil {
651			t.Fatalf("ProxyTransfer: %v", err)
652		}
653		if pres.ItemID != "i1" || pres.ToID != "alice" || pres.Version != 2 {
654			t.Fatalf("proxy result = %+v", pres)
655		}
656	}
