480		errs := make([]error, n)
481		wg.Add(n)
482		for i := 0; i < n; i++ {
483			i := i
484			go func() {
485				defer wg.Done()
486				to := "bob"
487				if i%2 == 0 {
488					to = "carol"
489				}
490				if i%3 == 0 {
491					to = "dave"
492				}
493				_, errs[i] = r.Transfer(xferReq("alice", "i1", to, 1, fmt.Sprintf("c%d", i)))
494			}()
495		}
496		wg.Wait()
497		succ := 0
498		for _, e := range errs {
499			if e == nil {
500				succ++
501			}
502		}
503		if succ != 1 {
